import{_ as t,o as i,c as a,a2 as d}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Personnages Clés et Organisations","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0095-关键人物与组织.md","filePath":"fr/0095-关键人物与组织.md"}'),n={name:"fr/0095-关键人物与组织.md"};function s(r,e,o,l,u,c){return i(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="personnages-cles-et-organisations" tabindex="-1">Personnages Clés et Organisations <a class="header-anchor" href="#personnages-cles-et-organisations" aria-label="Permalink to &quot;Personnages Clés et Organisations&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>95</td></tr><tr><td>Module</td><td>Annexes et matériaux de référence</td></tr><tr><td>Mots-clés principaux</td><td>personnages clés, organisations importantes, rôles historiques, fonctions institutionnelles, civilisation symbiotique</td></tr></tbody></table><h2 id="i-notes" tabindex="-1">I. Notes <a class="header-anchor" href="#i-notes" aria-label="Permalink to &quot;I. Notes&quot;">​</a></h2><p>Ce document recense les personnages clés et les organisations importantes de l&#39;histoire de la Civilisation Symbiotique de l&#39;Ancre, classés par période historique et par type d&#39;organisation. La section des personnages clés indique pour chaque personnage le nom, la période, les contributions essentielles et la position historique ; la section des organisations importantes indique pour chaque organisation le nom, la date de fondation, les fonctions essentielles et le rôle historique. Ce document est mis à jour en continu ; à mesure que l&#39;histoire progresse et que les organisations évoluent, il sera continuellement complété et révisé.</p><h2 id="ii-personnages-cles" tabindex="-1">II. Personnages Clés <a class="header-anchor" href="#ii-personnages-cles" aria-label="Permalink to &quot;II. Personnages Clés&quot;">​</a></h2><h3 id="_2-1-pionniers-de-la-pensee-de-l-ere-pre-ancre" tabindex="-1">2.1 Pionniers de la pensée de l&#39;ère pré-Ancre <a class="header-anchor" href="#_2-1-pionniers-de-la-pensee-de-l-ere-pre-ancre" aria-label="Permalink to &quot;2.1 Pionniers de la pensée de l&#39;ère pré-Ancre&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom</th><th>Période</th><th>Contributions essentielles</th><th>Position historique</th></tr></thead><tbody><tr><td>Xuánhéng Zǐ</td><td>environ −500 millions d&#39;années</td><td>Le premier penseur à avoir systématiquement réfléchi au système de culture prédatrice ; proposa le prototype du concept de « symbiose » ; auteur du fragment subsistant de Fǎn Lüèduó Lùn (Traité contre la Prédation)</td><td>Le pionnier antique de la pensée symbiotique ; sa pensée, après un sommeil de centaines de millions d&#39;années, devint la source spirituelle de la Civilisation Symbiotique de l&#39;Ancre</td></tr><tr><td>Wànlíng Mǔ</td><td>environ −100 millions d&#39;années</td><td>Dirigea la première civilisation expérimentale symbiotique de grande ampleur ; bien que finalement détruite par les civilisations prédatrices, sa pratique prouva la faisabilité du système symbiotique</td><td>La précurseure de la pratique symbiotique, honorée par les générations suivantes comme la « Mère de la Symbiose »</td></tr><tr><td>Máo Jué Zhě</td><td>environ −10 000 ans</td><td>Un cultivateur du Premier Plan qui, au cours d&#39;une longue culture, perçut accidentellement un nœud stable du réseau de lois et découvrit le mécanisme de l&#39;Ancre</td><td>Le découvreur du mécanisme de l&#39;Ancre et l&#39;initiateur de l&#39;Ère de l&#39;Éveil de l&#39;Ancre</td></tr></tbody></table><h3 id="_2-2-fondateurs-de-l-ere-de-l-eveil-de-l-ancre" tabindex="-1">2.2 Fondateurs de l&#39;Ère de l&#39;Éveil de l&#39;Ancre <a class="header-anchor" href="#_2-2-fondateurs-de-l-ere-de-l-eveil-de-l-ancre" aria-label="Permalink to &quot;2.2 Fondateurs de l&#39;Ère de l&#39;Éveil de l&#39;Ancre&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom</th><th>Période</th><th>Contributions essentielles</th><th>Position historique</th></tr></thead><tbody><tr><td>Máo Dìng Gōng</td><td>−10 000 à −9200 ans</td><td>Disciple de Máo Jué Zhě ; étudia systématiquement le mécanisme de l&#39;Ancre ; établit la première Ancre artificielle ; auteur de Máodiǎn Yuánlǐ (Principes de l&#39;Ancre)</td><td>Le fondateur de la technologie de l&#39;Ancre et l&#39;inventeur de l&#39;Ancre artificielle</td></tr><tr><td>Gòngshēng Zǐ</td><td>−6000 à −5100 ans</td><td>Combina la technologie de l&#39;Ancre avec la pensée symbiotique ; fonda le système théorique de la « Symbiose de l&#39;Ancre » ; auteur de Máodiǎn Gòngshēng Lùn (Sur la Symbiose de l&#39;Ancre)</td><td>Le fondateur de la théorie de la Symbiose de l&#39;Ancre et le mentor intellectuel de la civilisation symbiotique</td></tr><tr><td>Héngyuán Gōng</td><td>−5000 à −4300 ans</td><td>Établit la première cité-État symbiotique fondée sur l&#39;Ancre, « Héngyuan Chéng », et repoussa avec succès les attaques des civilisations prédatrices</td><td>Le fondateur de la première cité-État symbiotique et un praticien du système symbiotique</td></tr><tr><td>Wànzú Shǐ</td><td>−2000 à −1200 ans</td><td>Initia la première « Grande Assemblée de Symbiose des Dix Mille Races » ; parcourut des dizaines de races pour prôner l&#39;union symbiotique</td><td>Le promoteur de l&#39;union des Dix Mille Races et un pionnier de la symbiose interraciale</td></tr></tbody></table><h3 id="_2-3-fondateurs-de-l-etat-a-la-periode-d-etablissement-du-systeme-symbiotique" tabindex="-1">2.3 Fondateurs de l&#39;État à la Période d&#39;établissement du système symbiotique <a class="header-anchor" href="#_2-3-fondateurs-de-l-etat-a-la-periode-d-etablissement-du-systeme-symbiotique" aria-label="Permalink to &quot;2.3 Fondateurs de l&#39;État à la Période d&#39;établissement du système symbiotique&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom</th><th>Période</th><th>Contributions essentielles</th><th>Position historique</th></tr></thead><tbody><tr><td>Lìxiàn Gōng</td><td>−1000 à −900 ans</td><td>Président du Comité de rédaction de la Constitution Symbiotique ; présida à la rédaction de la Constitution Symbiotique et la fit adopter par référendum populaire</td><td>Le principal rédacteur de la Constitution Symbiotique et le père fondateur du constitutionnalisme de la civilisation symbiotique</td></tr><tr><td>Zhífǎ Gōng</td><td>−900 à −780 ans</td><td>Premier président du Comité Exécutif Symbiotique ; présida à l&#39;établissement du système administratif et des mécanismes d&#39;application de la loi de la civilisation symbiotique</td><td>Le fondateur du système administratif symbiotique et le premier chef de l&#39;administration</td></tr><tr><td>Sīfǎ Mǔ</td><td>−900 à −800 ans</td><td>Première juge en chef du Tribunal Symbiotique ; établit le système judiciaire et le système de contrôle de constitutionnalité de la civilisation symbiotique</td><td>La fondatrice du système judiciaire symbiotique et la première cheffe de la justice</td></tr><tr><td>Sānbǎi Shī</td><td>−500 à −300 ans</td><td>Présida à l&#39;excavation et à la compilation des Trois Cents Systèmes de Culture d&#39;Origine ; dirigea l&#39;équipe qui acheva la vérification des Trois Cents Systèmes</td><td>Le compilateur en chef des Trois Cents Systèmes et le commandant en chef de l&#39;ingénierie de l&#39;ouverture de la culture</td></tr><tr><td>Bèizēng Gōng</td><td>−300 à −220 ans</td><td>Présida à la recherche sur l&#39;application technologique du Fruit Multiplicateur ; réalisa la percée d&#39;ingénierie de la technologie d&#39;amplification déductive au centuple</td><td>Le scientifique en chef de la technologisation du Fruit Multiplicateur et un promoteur du Système d&#39;Itération par Déduction</td></tr></tbody></table><h3 id="_2-4-dirigeants-de-la-periode-d-ouverture-et-d-activation" tabindex="-1">2.4 Dirigeants de la Période d&#39;ouverture et d&#39;activation <a class="header-anchor" href="#_2-4-dirigeants-de-la-periode-d-ouverture-et-d-activation" aria-label="Permalink to &quot;2.4 Dirigeants de la Période d&#39;ouverture et d&#39;activation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom</th><th>Période</th><th>Contributions essentielles</th><th>Position historique</th></tr></thead><tbody><tr><td>Kāifàng Gōng</td><td>−100 à −50 ans</td><td>Présida à l&#39;ouverture complète des Trois Cents Systèmes de Culture d&#39;Origine ; établit le système d&#39;allocation des ressources de culture et le réseau de mentors</td><td>Le commandant en chef de l&#39;ouverture des Trois Cents Systèmes et un praticien du « chemin pour chacun »</td></tr><tr><td>Jīhuó Gōng</td><td>−50 ans à l&#39;an un</td><td>Présida à la mise en œuvre de la Stratégie d&#39;activation de 20 % ; dirigea l&#39;équipe qui réalisa en 50 ans l&#39;objectif d&#39;activation de 20 % des êtres vivants</td><td>Le commandant en chef de la Stratégie d&#39;activation de 20 % et l&#39;initiateur d&#39;une nouvelle ère pour la civilisation symbiotique</td></tr><tr><td>Shēngwéi Gōng</td><td>l&#39;an un à 80</td><td>Présida au premier projet d&#39;élévation ; promut la mise en œuvre de la Voie d&#39;Élévation en Quatre Étapes ; réalisa la première élévation par étapes</td><td>L&#39;ingénieur en chef de la première élévation et le dirigeant de l&#39;ère de l&#39;élévation</td></tr></tbody></table><h3 id="_2-5-explorateurs-de-la-republique-des-dix-mille-races-et-de-l-ere-transplanaire" tabindex="-1">2.5 Explorateurs de la République des Dix Mille Races et de l&#39;ère transplanaire <a class="header-anchor" href="#_2-5-explorateurs-de-la-republique-des-dix-mille-races-et-de-l-ere-transplanaire" aria-label="Permalink to &quot;2.5 Explorateurs de la République des Dix Mille Races et de l&#39;ère transplanaire&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom</th><th>Période</th><th>Contributions essentielles</th><th>Position historique</th></tr></thead><tbody><tr><td>Wànzú Gòngzhǔ</td><td>100 à 200</td><td>Présida à la fondation de la République des Dix Mille Races ; promut la compilation du Registre des Dix Mille Races et les politiques d&#39;intégration interraciale</td><td>Le fondateur de la République des Dix Mille Races et le premier Souverain Suprême des Dix Mille Races</td></tr><tr><td>Wèimiàn Mǔ</td><td>500 à 650</td><td>Première directrice de l&#39;Administration des Plans ; présida au programme d&#39;exploration transplanaire de grande ampleur ; établit la base maîtresse des coordonnées de plans</td><td>La pionnière de l&#39;exploration transplanaire et la fondatrice du système de gestion des plans</td></tr><tr><td>Kǎogǔ Gōng</td><td>800 à 950</td><td>Présida à la maturation finale du schéma d&#39;archéologie à distance par Miroir de Réplication ; fit entrer l&#39;archéologie transplanaire dans l&#39;ère de l&#39;échelle</td><td>Le point culminant des schémas archéologiques et le fondateur de l&#39;archéologie transplanaire</td></tr><tr><td>Shílǜ Gōng</td><td>1000 à 1150</td><td>Présida à la percée de la technologie de régression temporelle ; promut l&#39;établissement du principe d&#39;observer d&#39;abord, puis intervenir dans les limites</td><td>Le leader de la technologie de régression temporelle et le concepteur des principes des lois temporelles</td></tr></tbody></table><h2 id="iii-organisations-importantes" tabindex="-1">III. Organisations Importantes <a class="header-anchor" href="#iii-organisations-importantes" aria-label="Permalink to &quot;III. Organisations Importantes&quot;">​</a></h2><h3 id="_3-1-institutions-de-pouvoir-supreme" tabindex="-1">3.1 Institutions de pouvoir suprême <a class="header-anchor" href="#_3-1-institutions-de-pouvoir-supreme" aria-label="Permalink to &quot;3.1 Institutions de pouvoir suprême&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisation</th><th>Date de fondation</th><th>Fonctions essentielles</th><th>Rôle historique</th></tr></thead><tbody><tr><td>Assemblée Délibérante de l&#39;Ancre</td><td>−900 ans</td><td>L&#39;institution de pouvoir suprême de la civilisation symbiotique, composée de représentants de toutes les races en proportion, exerçant le pouvoir législatif et le pouvoir de décision des affaires majeures</td><td>L&#39;institution suprême de décision de la civilisation symbiotique et la conceptrice de toutes les grandes lois et stratégies</td></tr><tr><td>Comité Exécutif Symbiotique</td><td>−900 ans</td><td>L&#39;institution administrative suprême de la civilisation symbiotique, chargée de l&#39;exécution de la constitution et des lois et de la gouvernance quotidienne</td><td>L&#39;organe administratif suprême de la civilisation symbiotique et l&#39;exécuteur des lois et politiques</td></tr><tr><td>Tribunal Symbiotique</td><td>−900 ans</td><td>L&#39;institution judiciaire suprême de la civilisation symbiotique, exerçant indépendamment le pouvoir judiciaire, chargée du contrôle de constitutionnalité et du jugement des affaires majeures</td><td>L&#39;organe judiciaire suprême de la civilisation symbiotique et le gardien de l&#39;état de droit</td></tr><tr><td>Comité de Supervision de l&#39;Ancre</td><td>−900 ans</td><td>Institution de supervision indépendante, chargée de superviser toutes les institutions de pouvoir afin de prévenir l&#39;abus de pouvoir</td><td>L&#39;organe de supervision indépendant de la civilisation symbiotique et un maillon clé de l&#39;équilibre des pouvoirs</td></tr></tbody></table><h3 id="_3-2-institutions-de-gestion-specialisees" tabindex="-1">3.2 Institutions de gestion spécialisées <a class="header-anchor" href="#_3-2-institutions-de-gestion-specialisees" aria-label="Permalink to &quot;3.2 Institutions de gestion spécialisées&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisation</th><th>Date de fondation</th><th>Fonctions essentielles</th><th>Rôle historique</th></tr></thead><tbody><tr><td>Administration des Plans</td><td>500</td><td>Chargée de la maintenance de la base maîtresse des coordonnées de plans, de l&#39;approbation des permis de traversée, de la gestion de l&#39;archéologie transplanaire et de la coordination de la diplomatie transplanaire</td><td>L&#39;autorité compétente de l&#39;interaction transplanaire et le gestionnaire de l&#39;exploration des plans</td></tr><tr><td>Comité des Lois Temporelles</td><td>1000</td><td>Chargé de l&#39;approbation des opérations de régression temporelle, de la recherche sur les lois temporelles et de la supervision de la prévention et du contrôle des paradoxes temporels</td><td>L&#39;institution d&#39;approbation et de supervision des opérations de régression temporelle et le gardien de la sécurité des lois temporelles</td></tr><tr><td>Comité d&#39;Audit des Lois Temporelles</td><td>1050</td><td>Chargé de l&#39;audit a posteriori des opérations de régression temporelle, confirmant qu&#39;aucune perturbation incontrôlée de la ligne temporelle n&#39;a été causée</td><td>L&#39;institution d&#39;audit indépendante des opérations temporelles et la dernière ligne de défense de la sécurité de la régression temporelle</td></tr><tr><td>Comité d&#39;Éthique Interplans</td><td>600</td><td>Formule et interprète les directives éthiques transplanaires, approuve les projets d&#39;interaction transplanaire à haut risque et traite les plaintes de violation de l&#39;éthique</td><td>L&#39;institution de supervision éthique de l&#39;interaction transplanaire et le gardien de la subjectivité civilisationnelle</td></tr><tr><td>Bureau d&#39;Audit de la Restitution des Connaissances</td><td>850</td><td>Chargé de l&#39;audit des opérations de restitution de connaissances, garantissant que le contenu restitué est conforme au principe de « restitution de connaissances uniquement »</td><td>L&#39;institution d&#39;audit de la restitution des connaissances et un maillon clé de la prévention de la pollution transplanaire</td></tr></tbody></table><h3 id="_3-3-institutions-de-recherche-et-d-education" tabindex="-1">3.3 Institutions de recherche et d&#39;éducation <a class="header-anchor" href="#_3-3-institutions-de-recherche-et-d-education" aria-label="Permalink to &quot;3.3 Institutions de recherche et d&#39;éducation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisation</th><th>Date de fondation</th><th>Fonctions essentielles</th><th>Rôle historique</th></tr></thead><tbody><tr><td>Institut de Recherche de l&#39;Ancre</td><td>−8000 ans</td><td>Recherche fondamentale et développement appliqué du mécanisme de l&#39;Ancre ; construction et maintenance des Ancres artificielles</td><td>L&#39;institution de recherche fondamentale de la technologie de l&#39;Ancre et l&#39;une des sources technologiques de la civilisation symbiotique</td></tr><tr><td>Comité de Compilation des Trois Cents Systèmes</td><td>−500 ans</td><td>Excavation, compilation, vérification et optimisation continue des Trois Cents Systèmes de Culture d&#39;Origine</td><td>L&#39;institution de compilation et de maintenance des Trois Cents Systèmes et le support technique de l&#39;ouverture de la culture</td></tr><tr><td>Alliance Universitaire Symbiotique</td><td>−700 ans</td><td>Consortium d&#39;enseignement supérieur et d&#39;éducation de culture, chargé de la formation des talents avancés et de la recherche académique</td><td>L&#39;alliance des plus hautes institutions d&#39;enseignement de la civilisation symbiotique et le cœur de la formation des talents et de l&#39;innovation académique</td></tr><tr><td>Académie d&#39;Archéologie Transplanaire</td><td>550</td><td>Forme des talents professionnels en archéologie transplanaire ; mène des recherches sur les technologies archéologiques et des innovations méthodologiques</td><td>Le centre de formation des talents et de recherche-développement technologique de l&#39;archéologie transplanaire</td></tr><tr><td>Institut de Recherche des Lois Temporelles</td><td>950</td><td>Recherche théorique fondamentale sur les lois temporelles et recherche-développement de la technologie de régression temporelle</td><td>L&#39;institution centrale de la recherche sur les lois temporelles et le berceau de la technologie de régression temporelle</td></tr></tbody></table><h3 id="_3-4-organisations-militaires-et-de-securite" tabindex="-1">3.4 Organisations militaires et de sécurité <a class="header-anchor" href="#_3-4-organisations-militaires-et-de-securite" aria-label="Permalink to &quot;3.4 Organisations militaires et de sécurité&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisation</th><th>Date de fondation</th><th>Fonctions essentielles</th><th>Rôle historique</th></tr></thead><tbody><tr><td>Forces de Défense Symbiotiques</td><td>−850 ans</td><td>La force de défense régulière de la civilisation symbiotique, chargée de la défense des plans et de la réponse aux menaces extérieures</td><td>La principale force militaire de la civilisation symbiotique et la défenseure de la sécurité nationale</td></tr><tr><td>Corps de Patrouille des Plans</td><td>520</td><td>Chargé des patrouilles et de la surveillance de sécurité des plans explorés et de la réponse aux incidents de sécurité transplanaires</td><td>La force de première ligne de la sécurité transplanaire et le mainteneur de l&#39;ordre des plans</td></tr><tr><td>Équipe d&#39;Urgence contre la Pollution des Lois</td><td>600</td><td>Chargée de la réponse d&#39;urgence aux incidents de pollution des lois et de pollution énergétique et de l&#39;élimination de la pollution</td><td>La force de traitement d&#39;urgence de la pollution des lois et la gardienne de l&#39;environnement cosmique</td></tr><tr><td>Unité d&#39;Urgence contre les Paradoxes Temporels</td><td>1020</td><td>Chargée de la réponse d&#39;urgence aux incidents de paradoxes temporels et des opérations de réparation causale</td><td>La force de traitement d&#39;urgence des paradoxes temporels et la garantie finale de la stabilité de la ligne temporelle</td></tr></tbody></table><h3 id="_3-5-organisations-civiles-et-sociales" tabindex="-1">3.5 Organisations civiles et sociales <a class="header-anchor" href="#_3-5-organisations-civiles-et-sociales" aria-label="Permalink to &quot;3.5 Organisations civiles et sociales&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organisation</th><th>Date de fondation</th><th>Fonctions essentielles</th><th>Rôle historique</th></tr></thead><tbody><tr><td>Grande Assemblée de Symbiose des Dix Mille Races</td><td>−2000 ans</td><td>Réunions périodiques des représentants de toutes les races, discutant des affaires de symbiose interraciale et favorisant les échanges culturels</td><td>Une plateforme importante d&#39;échange entre toutes les races et l&#39;organisation prédécesseure de la République des Dix Mille Races</td></tr><tr><td>Association des Cultivateurs</td><td>−600 ans</td><td>L&#39;organisation d&#39;autorégulation de la profession de cultivateur, chargée de la défense des droits des cultivateurs et de l&#39;élaboration des normes professionnelles</td><td>L&#39;organisation d&#39;autorégulation des cultivateurs et une promotrice de la normalisation de la profession de culture</td></tr><tr><td>Association des Consommateurs</td><td>−650 ans</td><td>Organisation de protection des droits des consommateurs, chargée de la défense des droits des consommateurs, de l&#39;éducation des consommateurs et de la supervision sociale</td><td>La porte-parole des droits des consommateurs et la superviseure sociale de l&#39;ordre du marché</td></tr><tr><td>Alliance pour la Protection de l&#39;Environnement</td><td>−550 ans</td><td>Organisation civile unie pour la protection de l&#39;environnement, chargée de la supervision environnementale, de l&#39;éducation environnementale et des activités bénévoles de restauration écologique</td><td>La force sociale de la protection de l&#39;environnement et une promotrice de la civilisation écologique cosmique</td></tr><tr><td>Association d&#39;Amitié Transplanaire</td><td>580</td><td>Organisation civile favorisant les échanges amicaux entre civilisations de plans, chargée de la diplomatie civile et des échanges culturels</td><td>La force centrale de la diplomatie civile transplanaire et un pont de compréhension entre les civilisations</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Les personnages clés et les organisations sont les vecteurs vivants de l&#39;histoire de la Civilisation Symbiotique de l&#39;Ancre. Des pionniers de la pensée antique aux dirigeants de la civilisation contemporaine, des institutions de pouvoir suprême aux organisations sociales civiles, chaque personnage et chaque organisation joue un rôle irremplaçable dans le grand récit de la civilisation symbiotique. Leurs luttes et leurs contributions tissent ensemble l&#39;épopée magnifique de la Civilisation Symbiotique de l&#39;Ancre — du néant à l&#39;existence, de petit à grand, de son propre plan à l&#39;univers entier.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>70-纪元划分总表 (Tableau Maître de la Division des Ères)</li><li>49-治理框架与权力制衡 (Cadre de Gouvernance et Équilibre des Pouvoirs)</li><li>77-万族共和成立 (La Fondation de la République des Dix Mille Races)</li></ul>',30)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
